"""Offline annual-report comparison UI, with charts only for longer series."""
import json


def dashboard_html(data):
    payload = json.dumps(data, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return TEMPLATE.replace('__DATA__', payload)


TEMPLATE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{box-sizing:border-box}html,body{margin:0;background:transparent;color:#28243d;font-family:Inter,"Microsoft YaHei",Arial,sans-serif}button{font:inherit}main{padding:2px 2px 18px;overflow:hidden}.heading{display:flex;align-items:center;justify-content:space-between;margin:0 2px 14px}.heading p{margin:0;color:#817c90;font-size:13px}.heading strong{color:#7655f7}.nav{display:flex;gap:8px}.nav button{border:1px solid #e8e4f1;background:white;border-radius:11px;color:#5e5773;cursor:pointer;width:37px;height:37px;font-size:21px;transition:transform .2s,background .2s}.nav button:hover{transform:translateY(-2px);background:#f2edff}.rail{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;padding:2px 2px 16px;scrollbar-width:thin;scrollbar-color:#c5b9fa transparent}.card{flex:0 0 clamp(195px,23.5%,250px);min-height:149px;border:1px solid #e9e5f1;border-radius:21px;text-align:left;padding:20px;scroll-snap-align:start;cursor:pointer;color:#2b2540;background:var(--card-bg);transition:transform .25s,box-shadow .25s,border-color .25s;position:relative;overflow:hidden}.card::after{content:'';position:absolute;width:86px;height:86px;border:15px solid var(--card-art);border-radius:50%;right:-20px;top:-23px;opacity:.22}.card:hover{transform:translateY(-4px);box-shadow:0 12px 25px #27204414}.card[aria-pressed=true]{border:2px solid var(--accent);box-shadow:0 9px 24px #5139a51f}.card .label{font-size:13px;font-weight:650;position:relative;z-index:1}.card .value{font-size:28px;font-weight:800;letter-spacing:-1px;margin:14px 0 8px;white-space:nowrap;position:relative;z-index:1}.card .note{font-size:11px;line-height:1.5;color:#6a6476;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;position:relative;z-index:1}.card:first-child{background:#7655f7;color:white}.card:first-child .note{color:#eee8ff}.card:first-child[aria-pressed=true]{border-color:#301b9f}.detail{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(290px,.85fr);gap:16px;margin-top:3px}.panel{background:#fff;border:1px solid #eae6f2;border-radius:24px;padding:23px;min-height:316px;overflow:hidden}.eyebrow{font-size:10px;letter-spacing:2px;color:#988dad;font-weight:750}.panel h3{font-size:21px;letter-spacing:-.5px;margin:8px 0 5px}.subtitle{font-size:12px;color:#878194;line-height:1.6}.values{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:19px 0 14px}.value-box{background:#f8f7fc;border:1px solid #eeebf5;border-radius:17px;padding:15px}.value-box.current{background:#f1edff;border-color:#ded4ff}.year{color:#817b90;font-size:12px}.big{font-size:23px;font-weight:790;letter-spacing:-.5px;margin-top:8px;white-space:nowrap}.bars{display:grid;gap:12px;margin:18px 0 8px}.bar-row{display:grid;grid-template-columns:42px 1fr;align-items:center;gap:10px;font-size:11px;color:#817b90}.track{height:11px;background:#f3f0f8;border-radius:20px;overflow:hidden}.fill{height:100%;background:#c7bde6;border-radius:20px;min-width:2px}.bar-row:last-child .fill{background:var(--accent)}.delta{display:flex;align-items:center;gap:11px;margin-top:17px;flex-wrap:wrap}.delta strong{background:#f1ecff;color:#6046c4;border-radius:11px;padding:9px 12px;font-size:15px}.delta span{color:#716b7e;font-size:12px}.note{font-size:12px;color:#817b90;line-height:1.7;margin-top:15px}.insight{background:#f6f3ff;border-radius:18px;padding:17px;margin:21px 0 18px}.insight .number{font-size:26px;font-weight:800;color:#6046c4;margin:9px 0}.insight p{font-size:12px;color:#6d647e;line-height:1.7;margin:0}.source{border-top:1px solid #f0edf5;padding-top:13px;color:#817b90;font-size:11px;line-height:1.8;white-space:pre-line}.trend{height:185px;margin-top:13px}.trend svg{width:100%;height:100%;overflow:visible}.grid{stroke:#eeeaf5;stroke-width:1}.axis{font-size:11px;fill:#938da2}.line{fill:none;stroke:var(--accent);stroke-width:3;stroke-linejoin:round;stroke-linecap:round}.dot{fill:#fff;stroke:var(--accent);stroke-width:3}.empty{display:flex;align-items:center;justify-content:center;text-align:center;min-height:165px;color:#817b90;font-size:13px;line-height:1.7;padding:15px}.fade{animation:fade .3s ease-out}@keyframes fade{from{opacity:.3;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(max-width:760px){.detail{grid-template-columns:1fr}.card{flex-basis:198px}.panel{min-height:290px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
</style></head><body><script id="payload" type="application/json">__DATA__</script><main>
<div class="heading"><p>选择指标，查看 <strong id="year"></strong> 年的经营变化</p><div class="nav"><button id="left" aria-label="向左滚动指标">‹</button><button id="right" aria-label="向右滚动指标">›</button></div></div>
<div class="rail" id="rail" role="group" aria-label="财务指标"></div>
<div class="detail"><section class="panel" id="comparison"></section><section class="panel" id="context"></section></div></main>
<script>
const data=JSON.parse(document.getElementById('payload').textContent),cards=data.cards;
const palette=['#7655f7','#ff784f','#18aa96','#eaaa28','#e954a7','#4d8fea','#00a9be','#a668e6'];
const backgrounds=['#7655f7','#fff0e9','#e3f7f1','#fff7d9','#fce9f2','#eaf1ff','#e8f7fa','#f4ecff'];
const rail=document.getElementById('rail');let selected=0;
document.getElementById('year').textContent=data.year;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fixed=n=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const signed=n=>(n>=0?'+':'')+fixed(n);
const fmt=(n,c)=>c.format==='percent'?fixed(n)+'%':fixed(n)+' '+c.display_unit;
const change=c=>{const pair=c.comparison;if(!pair)return '';return c.format==='percent'?`较上年 ${signed(pair.delta)} 个百分点`:pair.rate===null?`差额 ${signed(pair.delta)} ${c.display_unit}`:`较上年 ${signed(pair.rate)}%`};
const page=p=>p.pages.length?p.pages.join('、'):'未标注';
const year=p=>p.year+(p.restated?'（重述）':'');
function drawRail(){rail.innerHTML=cards.map((c,i)=>{const p=c.current,note=c.comparison?change(c):(p?`PDF ${page(p)} 页`:c.reason||'暂无可核对数据');return `<button type="button" class="card" data-index="${i}" aria-pressed="${i===selected}" style="--accent:${palette[i%palette.length]};--card-bg:${backgrounds[i%backgrounds.length]};--card-art:${palette[i%palette.length]}"><div class="label">${esc(c.label)}</div><div class="value">${p?esc(fmt(p.value,c)):'—'}</div><div class="note" title="${esc(note)}">${esc(note)}</div></button>`}).join('')}
rail.addEventListener('click',e=>{const b=e.target.closest('.card');if(b){selected=+b.dataset.index;render()}});
document.getElementById('left').onclick=()=>rail.scrollBy({left:-rail.clientWidth*.75,behavior:'smooth'});
document.getElementById('right').onclick=()=>rail.scrollBy({left:rail.clientWidth*.75,behavior:'smooth'});
function render(){const c=cards[selected],p=c.current,pair=c.comparison,accent=palette[selected%palette.length],left=document.getElementById('comparison'),right=document.getElementById('context');document.documentElement.style.setProperty('--accent',accent);document.querySelectorAll('.card').forEach((el,i)=>el.setAttribute('aria-pressed',i===selected));let body='';if(pair){const prior=pair.previous,max=Math.max(p.value,prior.value,0),bars=p.value>=0&&prior.value>=0&&max>0?`<div class="bars"><div class="bar-row"><span>${prior.year}</span><div class="track"><div class="fill" style="width:${Math.max(1,prior.value/max*100)}%"></div></div></div><div class="bar-row"><span>${p.year}</span><div class="track"><div class="fill" style="width:${Math.max(1,p.value/max*100)}%"></div></div></div></div>`:'';body=`<div class="values"><div class="value-box"><div class="year">${esc(year(prior))} 年</div><div class="big">${esc(fmt(prior.value,c))}</div></div><div class="value-box current"><div class="year">${esc(year(p))} 年</div><div class="big">${esc(fmt(p.value,c))}</div></div></div>${bars}<div class="delta"><strong>${esc(c.format==='percent'?signed(pair.delta)+' 个百分点':signed(pair.delta)+' '+c.display_unit)}</strong><span>${esc(pair.delta===0?'与上年持平':pair.delta>0?'较上年增加':'较上年减少')}${pair.rate!==null?' · '+esc(signed(pair.rate))+'%':''}</span></div>${!bars?'<div class="note">数值含零或负值，未用长度条暗示规模。</div>':''}`;}else if(p){body=`<div class="values"><div class="value-box current"><div class="year">${esc(year(p))} 年</div><div class="big">${esc(fmt(p.value,c))}</div></div></div><div class="empty">${esc(c.comparison_reason||'缺少可比的上一年度数据，暂不计算变化。')}</div>`;}else{body=`<div class="empty">${esc(c.comparison_reason||c.reason||'当前年度暂无可核对数据')}</div>`;}left.innerHTML=`<div class="eyebrow">YEAR-ON-YEAR COMPARISON</div><h3>${esc(c.label)} · 年度对比</h3><div class="subtitle">${c.format==='percent'?'百分比指标 · 差额使用百分点':esc((p||c.points[0])?.currency||'金额')+' · '+c.display_unit} · 仅比较相邻且口径兼容的年度</div><div class="fade">${body}</div>`;const sources=[pair?.previous,p].filter(Boolean).map(q=>`${year(q)} 年 · PDF ${page(q)} 页`).join('\n');if(c.can_trend){right.innerHTML=`<div class="eyebrow">MULTI-YEAR TREND</div><h3>连续年度趋势</h3><div class="subtitle">${c.points.length} 个连续、同口径的可比年度</div><div class="trend fade">${trendSvg(c)}</div><div class="source">${esc(sources)}</div>`;}else{const status=pair?(pair.delta===0?'与上年持平':pair.delta>0?'较上年增加':'较上年减少'):'暂无可靠的相邻年度对比';const detail=pair?(c.format==='percent'?`${signed(pair.delta)} 个百分点`:pair.rate===null?`差额 ${signed(pair.delta)} ${c.display_unit}`:`${signed(pair.rate)}%`):'—';right.innerHTML=`<div class="eyebrow">CHANGE AT A GLANCE</div><h3>变化一目了然</h3><div class="subtitle">两年数据直接对照，避免制造趋势感</div><div class="insight fade"><div class="year">${esc(status)}</div><div class="number">${esc(detail)}</div><p>${pair&&c.format==='money'&&pair.rate===null?'上年基数为零或负数，不计算常规增长率。':pair?'变化仅说明数值方向，不代表经营质量改善或恶化。':esc(c.comparison_reason||'数据不足时不补零、不推测变化。')}</p></div><div class="source">${esc(sources||c.reason||'请在详细数据中核对来源。')}</div>`;}}
function trendSvg(c){const points=c.points.slice().sort((a,b)=>a.year-b.year),w=380,h=180,L=48,R=15,T=16,B=30,vals=points.map(p=>p.value),min=Math.min(0,...vals),max=Math.max(0,...vals),span=max-min||1,x=i=>L+(w-L-R)*i/(points.length-1),y=v=>T+(h-T-B)*(max-v)/span,grid=[0,.5,1].map(t=>{const yy=T+(h-T-B)*t;return `<line class="grid" x1="${L}" x2="${w-R}" y1="${yy}" y2="${yy}"/><text class="axis" x="${L-5}" y="${yy+4}" text-anchor="end">${fixed(max-span*t)}</text>`}).join(''),ticks=points.map((p,i)=>`<text class="axis" x="${x(i)}" y="${h-8}" text-anchor="middle">${p.year}</text>`).join(''),path=points.map((p,i)=>(i?'L':'M')+x(i)+' '+y(p.value)).join(' '),dots=points.map((p,i)=>`<circle class="dot" cx="${x(i)}" cy="${y(p.value)}" r="4"><title>${p.year} 年 · ${esc(fmt(p.value,c))} · PDF ${esc(page(p))} 页</title></circle>`).join('');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(c.label)}连续年度趋势">${grid}${ticks}<path class="line" d="${path}"/>${dots}</svg>`}
drawRail();render();
</script></body></html>'''
